//! End-to-end calendar contracts. Expected instants are hand-written, never
//! generated by the recurrence or timezone implementation under test.
use super::*;

fn check_calendar(text: &str, starts: &[&str], display_tz: Tz, all_day: bool) -> Vec<Event> {
    let events = extract_events_for_year(text, &display_tz, false, 2024).unwrap();
    assert_eq!(events.len(), starts.len(), "unexpected occurrence count");
    for (event, expected) in events.iter().zip(starts) {
        let expected = DateTime::parse_from_rfc3339(expected).unwrap();
        assert_eq!(event.start_timestamp.timestamp(), expected.timestamp());
        assert_eq!(event.start_timestamp.timezone(), display_tz);
        assert_eq!(event.all_day, all_day);
        assert_eq!(event.summary, "Fixture meeting");
        assert_eq!(
            event.end_timestamp.timestamp(),
            expected.timestamp() + if all_day { 86400 } else { 3600 },
            "unexpected occurrence end"
        );
    }
    events
}

macro_rules! calendar_case {
    ($name:ident, $zone:expr, $all_day:expr, [$($start:literal),* $(,)?]) => {
        #[test]
        fn $name() {
            check_calendar(
                include_str!(concat!("../tests/fixtures/calendars/", stringify!($name), ".ics")),
                &[$($start),*], $zone, $all_day,
            );
        }
    };
}

