#[test]
fn organizer_and_viewer_change_dst_on_different_dates() {
    let events = check_calendar(
        include_str!("../tests/fixtures/calendars/new_york_spring.ics"),
        &[
            "2024-03-03T14:00:00Z",
            "2024-03-10T13:00:00Z",
            "2024-03-17T13:00:00Z",
            "2024-03-24T13:00:00Z",
            "2024-03-31T13:00:00Z",
        ],
        chrono_tz::Europe::Berlin,
        false,
    );
    let wall_times: Vec<_> = events
        .iter()
        .map(|e| e.start_timestamp.format("%H:%M").to_string())
        .collect();
    assert_eq!(wall_times, ["15:00", "14:00", "14:00", "14:00", "15:00"]);
}

