#[test]
fn exchange_transition_instant() {
    let calendar = parse_calendar(include_str!(
        "../tests/fixtures/calendars/exchange_transition.ics"
    ))
    .unwrap()
    .unwrap();
    let zones = parse_ical_timezones(&calendar, 2024).unwrap();
    let zone = &zones["Exchange Western Europe"];
    // Local onset 02:00 with TZOFFSETFROM:+0100 means 01:00 UTC.
    for (utc, expected) in [
        ("2024-03-31T00:59:59Z", "2024-03-31T01:59:59+01:00"),
        ("2024-03-31T01:00:00Z", "2024-03-31T03:00:00+02:00"),
        ("2024-03-31T01:00:01Z", "2024-03-31T03:00:01+02:00"),
        ("2024-10-27T00:59:59Z", "2024-10-27T02:59:59+02:00"),
        ("2024-10-27T01:00:00Z", "2024-10-27T02:00:00+01:00"),
        ("2024-10-27T01:00:01Z", "2024-10-27T02:00:01+01:00"),
    ] {
        let actual = DateTime::parse_from_rfc3339(utc)
            .unwrap()
            .with_timezone(zone);
        assert_eq!(actual.to_rfc3339(), expected);
    }
}

